alt?: string;
size?: number;

dtsPropsFor.DataTable:
columns: { key: string; header: React.ReactNode; /** tabular-nums for anything compared. */ numeric?: boolean; width?: number | string; render?: (row: any) => React.ReactNode }[];
rows: any[];
onRowClick?: (row: any) => void;
rowKey?: (row: any, index: number) => React.Key;

dtsPropsFor.DetailList:
items: { label: React.ReactNode; value?: React.ReactNode; /** Tabular numerals — phones, dates, counts, codes. */
numeric?: boolean }[];
/** 1 on narrow columns and tablet, 2 on a desktop detail surface. */
columns?: number;
style?: React.CSSProperties;

dtsPropsFor.EmptyState:
/** lucide name. */
icon?: string;
title: React.ReactNode;
description?: React.ReactNode;
